-- Demo data: one society (join code GREEN1), its flats, one store and a starter catalog.
-- After signing in once with the store owner's phone, run in the SQL editor:
--   select assign_store_owner('+91XXXXXXXXXX', '00000000-0000-0000-0000-0000000000a1');

values ('00000000-0000-0000-0000-000000000001', 'Green Meadows', 'Whitefield, Bengaluru', 'GREEN1');

select '00000000-0000-0000-0000-000000000001', b, (f * 100 + n)::text
from unnest(array['A', 'B', 'C']) b, generate_series(1, 4) f, generate_series(1, 4) n;

values ('00000000-0000-0000-0000-0000000000a1', '00000000-0000-0000-0000-000000000001', 'Meadows Daily Needs', 50, 0);


